"""Evaluate the small spreadsheet language described in README.md."""

import re


class CycleError(Exception):
    """Raised when a cell depends on itself, directly or indirectly."""


_TOKEN_RE = re.compile(
    r"(?P<number>(?:\d+(?:\.\d*)?|\.\d+))"
    r"|(?P<reference>[A-Za-z]+\d*)"
    r"|(?P<operator>[+\-*/^()])"
)


class _FormulaParser:
    def __init__(self, formula, resolve):
        self._tokens = self._tokenize(formula)
        self._index = 0
        self._resolve = resolve

    @staticmethod
    def _tokenize(formula):
        tokens = []
        position = 0
        while position < len(formula):
            if formula[position].isspace():
                position += 1
                continue

            match = _TOKEN_RE.match(formula, position)
            if match is None:
                raise ValueError(f"invalid token at position {position}")
            tokens.append((match.lastgroup, match.group()))
            position = match.end()

        tokens.append(("end", ""))
        return tokens

    def parse(self):
        value = self._expression()
        if self._current()[0] != "end":
            raise ValueError(f"unexpected token {self._current()[1]!r}")
        return value

    def _current(self):
        return self._tokens[self._index]

    def _take_operator(self, operator):
        kind, value = self._current()
        if kind == "operator" and value == operator:
            self._index += 1
            return True
        return False

    def _expression(self):
        value = self._term()
        while True:
            if self._take_operator("+"):
                value += self._term()
            elif self._take_operator("-"):
                value -= self._term()
            else:
                return value

    def _term(self):
        value = self._factor()
        while True:
            if self._take_operator("*"):
                value *= self._factor()
            elif self._take_operator("/"):
                value /= self._factor()
            else:
                return value

    def _factor(self):
        if self._take_operator("-"):
            return -self._factor()
        return self._power()

    def _power(self):
        value = self._primary()
        if self._take_operator("^"):
            value **= self._factor()
        return value

    def _primary(self):
        kind, value = self._current()
        if kind == "number":
            self._index += 1
            return float(value)
        if kind == "reference":
            self._index += 1
            return self._resolve(value)
        if self._take_operator("("):
            value = self._expression()
            if not self._take_operator(")"):
                raise ValueError("expected ')'")
            return value
        if kind == "end":
            raise ValueError("unexpected end of formula")
        raise ValueError(f"unexpected token {value!r}")


def evaluate(cells):
    """Return the computed floating-point value of every cell in *cells*."""
    values = {}
    states = {}
    stack = []

    def resolve(name):
        if name in values:
            return values[name]
        if states.get(name) == "visiting":
            cycle_start = stack.index(name)
            cycle = stack[cycle_start:] + [name]
            raise CycleError("dependency cycle: " + " -> ".join(cycle))

        raw_value = cells[name]
        states[name] = "visiting"
        stack.append(name)
        try:
            if raw_value.startswith("="):
                value = _FormulaParser(raw_value[1:], resolve).parse()
            else:
                value = float(raw_value)
            values[name] = value
            states[name] = "done"
            return value
        except Exception:
            states.pop(name, None)
            raise
        finally:
            stack.pop()

    for name in cells:
        resolve(name)
    return values

